import time
from six.moves import queue
from moler.device.device import DeviceFactory
import logging


class RtgMmiDataStream(object):
    """Data stream providing data collected from real Rtg MMI output"""

    def __init__(self, device_name):
        """
        Data stream connecting to MMI of RTG

        :param device_name: MMI device name inside Moler configuration
        """
        self.mmi = DeviceFactory.get_device(name=device_name, initial_state='UNIX_LOCAL')  # take specific device out of available ones
        self.number_of_related_devices = 0
        self.closed = True
        self.logger = logging.getLogger('messaging')
        self.received_data_queue = queue.Queue()

    def __str__(self):
        return "{}({})".format(self.__class__.__name__, self.mmi.name)

    def open(self):
        """
        Open connection to MMI of RTG
        :return: None
        """
        self.logger.info('{}.open() called'.format(self))
        # register function observing data of connection
        self.mmi.io_connection.moler_connection.subscribe(self._buffer_data, self._drop_buffered_data)
        self.mmi.goto_state(state="UNIX_REMOTE")
        if self.mmi.current_state == "UNIX_REMOTE":
            self.closed = False

    def close(self):
        """
        Close connection to MMI of RTG
        :return: None
        """
        self.logger.info('{}.close() called'.format(self))
        self._close()

    def _close(self):
        """
        Close connection to MMI of RTG
        :return: None
        """
        if not self.closed:
            self.mmi.goto_state(state='UNIX_LOCAL')
            self.mmi.io_connection.moler_connection.unsubscribe(self._buffer_data, self._drop_buffered_data)
            if self.mmi.current_state == 'UNIX_LOCAL':
                # TODO: all data buffered inside self.received_data_queue should be send to logs
                #       means: no data after direct close()
                self._drop_buffered_data()
                # TODO: but in case of connection drop they should be retrieved by read() before read() returns None
                #       means: flush data after connection drop
                self.closed = True

    # TODO: track state changes and update self.closed - means add connection drop detection

    def read(self):
        """
        Read data observed at connection to MMI of RTG
        :return: chunk of MMI output (string)
        """
        try:
            if self.closed:
                chunk = None
            else:
                chunk = self.received_data_queue.get(block=True, timeout=1)
                self.received_data_queue.task_done()
        except queue.Empty:  # timeout of get()
            chunk = ""
        return chunk

    def _buffer_data(self, data, *_args, **_kwargs):
        try:
            self.received_data_queue.put_nowait(data)  # we can't block in moler connection callback
        except queue.Full:
            pass  # TODO: add warning into logs

    def _drop_buffered_data(self):
        buffered_chunks_nb = self.received_data_queue.qsize()
        if buffered_chunks_nb == 0:
            return
        # print("data stream close - dropping buffered data:")
        for idx in range(buffered_chunks_nb):
            try:
                self.received_data_queue.get(block=False)
            except queue.Empty:
                pass

            # print("CHUNK{}: [{}]".format(idx, chunk))


class RtgMmiLogDataStream(object):
    """Data stream providing data from logfile holding Rtg MMI output"""

    def __init__(self, log_filename, play_log_start_delay=0):
        """
        Data stream replaying Rtg MMI logfile

        :param log_filename: path to log with Rtg MMI output
        """
        self.log_filename = log_filename
        self._connection = None
        self.play_log_start_delay = play_log_start_delay
        self._play_log_started = False

    def __str__(self):
        if self.play_log_start_delay:
            return "{}({}, {}s)".format(self.__class__.__name__, self.log_filename, self.play_log_start_delay)
        else:
            return "{}({})".format(self.__class__.__name__, self.log_filename)

    def open(self):
        """
        Open 'virtual' connection to MMI of RTG via opening Rtg MMI log
        :return: None
        """
        self._connection = open(self.log_filename)

    def close(self):
        """
        Close 'virtual' connection to MMI of RTG
        :return: None
        """
        self._connection.close()

    @property
    def closed(self):
        """
        Return 'closed' status of  'virtual' connection to MMI of RTG
        :return: True - closed, False - open
        """
        if self._connection is None:
            return True
        return self._connection.closed

    def read(self):
        """
        Read data of  'virtual' connection to MMI of RTG
        :return: chunk of MMI output (string)
        """
        if not self._play_log_started:
            time.sleep(self.play_log_start_delay)
            self._play_log_started = True
        try:
            chunk = self._connection.read(200)
            if chunk == "":  # reached EOF
                chunk = None
        except Exception as err:
            if self.closed:
                chunk = None
            else:
                # TODO: log it
                print("{!r} while reading from open file {}".format(err, self._connection.name))   # noqa: T201
                chunk = None
        return chunk
